+-- Add service column to track which service should process a job
+-- Existing jobs default to NULL (will be claimed by internal worker)
+-- New jobs can specify 'notifications' or other service names
+
+ALTER TABLE jobs ADD COLUMN service VARCHAR(255) NULL;
+
+-- Create index for faster lookups by service and status
+CREATE INDEX idx_jobs_service_status ON jobs(service, status, created_at);
