+import * as http from "http";
+import { claimNext, completeJob, Job } from "./jobs.ts";
+
+const PORT = process.env.API_PORT || 3000;
+const API_KEY = process.env.JOB_QUEUE_API_KEY || "default-key";
+
+const authenticate = (req: http.IncomingMessage): boolean => {
+  const authHeader = req.headers.authorization || "";
+  const providedKey = authHeader.replace("Bearer ", "");
+  return providedKey === API_KEY;
+};
+
+const sendJsonResponse = (
+  res: http.ServerResponse,
+  statusCode: number,
+  data: unknown,
+) => {
+  res.writeHead(statusCode, { "Content-Type": "application/json" });
+  res.end(JSON.stringify(data));
+};
+
+const handleClaimJob = async (
+  req: http.IncomingMessage,
+  res: http.ServerResponse,
+  service: string,
+): Promise<void> => {
+  if (!authenticate(req)) {
+    sendJsonResponse(res, 401, { error: "Unauthorized" });
+    return;
+  }
+
+  const job = await claimNext(service);
+  if (job === null) {
+    sendJsonResponse(res, 204, null);
+    return;
+  }
+
+  sendJsonResponse(res, 200, job);
+};
+
+const handleCompleteJob = async (
+  req: http.IncomingMessage,
+  res: http.ServerResponse,
+  jobId: string,
+): Promise<void> => {
+  if (!authenticate(req)) {
+    sendJsonResponse(res, 401, { error: "Unauthorized" });
+    return;
+  }
+
+  if (req.method !== "POST") {
+    sendJsonResponse(res, 405, { error: "Method not allowed" });
+    return;
+  }
+
+  await completeJob(jobId);
+  sendJsonResponse(res, 200, { status: "completed" });
+};
+
+export const createServer = (): http.Server => {
+  return http.createServer(async (req, res) => {
+    const url = new URL(req.url || "", `http://${req.headers.host}`);
+    const pathname = url.pathname;
+
+    if (pathname.startsWith("/jobs/claim/")) {
+      const service = pathname.slice("/jobs/claim/".length);
+      await handleClaimJob(req, res, service);
+    } else if (pathname.startsWith("/jobs/") && pathname.endsWith("/complete")) {
+      const jobId = pathname.slice("/jobs/".length, -"/complete".length);
+      await handleCompleteJob(req, res, jobId);
+    } else {
+      sendJsonResponse(res, 404, { error: "Not found" });
+    }
+  });
+};
+
+export const startServer = (): Promise<void> => {
+  const server = createServer();
+  return new Promise((resolve) => {
+    server.listen(PORT, () => {
+      console.log(`Job queue API listening on port ${PORT}`);
+      resolve();
+    });
+  });
+};
